html:
{% set currency = doc.currency or 'KES' %}
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Courier New', Courier, monospace;
    font-size: 11px;
    width: 72mm;
    margin: 0 auto;
    padding: 3mm 2mm 6mm;
    color: #000;
  }
  .center { text-align: center; }
  .right  { text-align: right; }
  .bold   { font-weight: bold; }
  .company { font-size: 13px; font-weight: bold; text-align: center; margin-bottom: 2px; }
  .divider { border: none; border-top: 1px dashed #000; margin: 4px 0; }
  table { width: 100%; border-collapse: collapse; }
  th, td { font-size: 11px; padding: 1px 0; vertical-align: top; }
  td.qty   { width: 10%; text-align: right; white-space: nowrap; }
  td.rate  { width: 24%; text-align: right; white-space: nowrap; }
  td.amt   { width: 26%; text-align: right; white-space: nowrap; }
  td.desc  { width: 40%; word-break: break-word; }
  .totals td { border-top: none; }
  .totals tr.grand td { font-weight: bold; font-size: 12px; }
  .footer { text-align: center; font-size: 10px; margin-top: 6px; }
</style>
</head>
<body>

{%- set company_name = doc.company or '' %}
{%- set addr = frappe.db.get_value('Company', company_name, ['address', 'phone_no', 'email'], as_dict=True) or {} %}

<div class="company">{{ company_name }}</div>
{% if addr.get('address') %}<div class="center">{{ addr.address | replace('\n', ', ') }}</div>{% endif %}
{% if addr.get('phone_no') %}<div class="center">Tel: {{ addr.phone_no }}</div>{% endif %}
{% if addr.get('email') %}<div class="center">{{ addr.email }}</div>{% endif %}

<hr class="divider">

<div class="center bold">SALES RECEIPT</div>

<hr class="divider">

<table>
  <tr><td>Receipt No:</td><td class="right">{{ doc.name }}</td></tr>
  <tr><td>Date:</td><td class="right">{{ doc.posting_date }} {{ doc.posting_time[:5] if doc.posting_time else '' }}</td></tr>
  <tr><td>Customer:</td><td class="right">{{ doc.customer_name or doc.customer }}</td></tr>
  {% if doc.posa_cashier or doc.owner %}
  <tr><td>Cashier:</td><td class="right">{{ doc.posa_cashier or doc.owner }}</td></tr>
  {% endif %}
</table>

<hr class="divider">

<table>
  <thead>
    <tr>
      <th class="desc">Item</th>
      <th class="qty">Qty</th>
      <th class="rate">Rate</th>
      <th class="amt">Amount</th>
    </tr>
  </thead>
  <tbody>
  {%- for item in doc.items %}
    <tr>
      <td class="desc">{{ item.item_name or item.item_code }}</td>
      <td class="qty">{{ item.qty | int if item.qty == (item.qty | int) else item.qty }}</td>
      <td class="rate">{{ frappe.utils.fmt_money(item.rate, currency=currency) }}</td>
      <td class="amt">{{ frappe.utils.fmt_money(item.amount, currency=currency) }}</td>
    </tr>
  {%- endfor %}
  </tbody>
</table>

<hr class="divider">

<table class="totals">
  <tr><td>Net Total</td><td class="right">{{ frappe.utils.fmt_money(doc.net_total, currency=currency) }}</td></tr>
  {%- for tax in doc.taxes %}
    {%- if tax.tax_amount %}
  <tr><td>{{ tax.description }}{% if tax.rate %} ({{ tax.rate }}%){% endif %}</td><td class="right">{{ frappe.utils.fmt_money(tax.tax_amount, currency=currency) }}</td></tr>
    {%- endif %}
  {%- endfor %}
  {%- if doc.discount_amount %}
  <tr><td>Discount</td><td class="right">-{{ frappe.utils.fmt_money(doc.discount_amount, currency=currency) }}</td></tr>
  {%- endif %}
  <tr class="grand"><td>TOTAL</td><td class="right">{{ frappe.utils.fmt_money(doc.rounded_total or doc.grand_total, currency=currency) }}</td></tr>
</table>

<hr class="divider">

<table>
{%- for pay in doc.payments %}
  {%- if pay.amount %}
  <tr>
    <td>{{ pay.mode_of_payment }}</td>
    <td class="right">{{ frappe.utils.fmt_money(pay.amount, currency=currency) }}</td>
  </tr>
  {%- if pay.get('posa_reference_code') %}
  <tr>
    <td style="padding-left:8px; color:#444;">Ref: {{ pay.posa_reference_code }}</td>
    <td></td>
  </tr>
  {%- endif %}
  {%- endif %}
{%- endfor %}
</table>

{%- if doc.change_amount %}
<table>
  <tr><td>Change</td><td class="right">{{ frappe.utils.fmt_money(doc.change_amount, currency=currency) }}</td></tr>
</table>
{%- endif %}

<hr class="divider">

{% if doc.terms %}<div style="font-size:10px; margin-bottom:4px;">{{ doc.terms }}</div>{% endif %}
<div class="footer">Thank you, please visit again.</div>
<div class="footer" style="margin-top:3px;">{{ doc.posting_date }}</div>

</body>
</html>
